using System;
using System.Linq;
namespace MochiDesktop {
 public static class GoogleWebWorkflowTests {
  static void Assert(bool condition,string error){if(!condition)throw new Exception(error);}
  static GoogleWebPlan Parse(string text,DateTime now){return Commands.Parse(text,new StoredState(),now).GoogleWorkflow;}
  public static void Add(Action<string,Action> test){var now=new DateTime(2026,10,27,8,0,0,DateTimeKind.Utc);
   test("Native Gmail unread variations build review-only web plans",delegate{foreach(string text in new[]{"show unread emails","check my unread mail","please show unread Gmail","could you please find unread messages"}){var p=Parse(text,now);Assert(p!=null&&p.Action=="search-mail"&&p.Url.EndsWith("#search/is%3Aunread"),"Unread variation failed: "+text);}});
   test("Gmail sender phrases preserve supported search operators",delegate{foreach(string text in new[]{"find emails from alex@example.com","search Gmail for from:alex@example.com","look for mail from alex@example.com"}){var p=Parse(text,now);Assert(p!=null&&Uri.UnescapeDataString(p.Url).EndsWith("#search/from:alex@example.com"),"Sender variation changed query");}});
   test("Gmail queries cannot inject a new URL parameter",delegate{var p=Parse("search Gmail for budget & account=other #secret",now);Assert(p!=null&&p.Url.Contains("%26")&&p.Url.Contains("%23")&&new Uri(p.Url).Host=="mail.google.com","Search text became URL structure");});
   test("Gmail inbox does not claim to read mail",delegate{var result=Commands.Parse("check my mail",new StoredState(),now);Assert(result.GoogleWorkflow!=null&&result.GoogleWorkflow.Url.EndsWith("#inbox")&&result.Url==null&&result.Reminder==null,"Inbox shortcut bypassed review");});
   test("Compose draft fields are encoded separately and never sent",delegate{var p=Parse("draft email to alex+tag@example.com subject Lunch & coffee body Are you free?",now);Assert(p!=null&&p.Action=="compose-mail"&&p.Url.Contains("to=alex%2Btag%40example.com")&&p.Url.Contains("su=Lunch%20%26%20coffee")&&p.Url.Contains("body=Are%20you%20free%3F")&&p.Description.Contains("review and send"),"Draft fields were changed or auto-sent");});
   test("Compose variants and colon labels are supported",delegate{foreach(string text in new[]{"compose an email to alex@example.com subject: Lunch body: Hello","write email to alex@example.com about Lunch saying Hello","send email to alex@example.com subject Lunch body Hello"}){var p=Parse(text,now);Assert(p!=null&&p.Action=="compose-mail"&&p.Url.Contains("body=Hello"),"Draft variation failed: "+text);}});
   test("Blank compose opens only a reviewable draft page",delegate{var p=Parse("compose email",now);Assert(p!=null&&p.Url=="https://mail.google.com/mail/?view=cm&fs=1"&&p.Description.Contains("sends nothing"),"Blank compose changed behavior");});
   test("Compose rejects multiple or malformed recipient addresses",delegate{foreach(string recipient in new[]{"not-an-address","a@example.com,b@example.com","a@example.com;evil","https://evil.example/"})Assert(Parse("draft email to "+recipient+" subject Hello",now)==null,"Invalid recipient accepted");});
   test("Google command control characters are rejected",delegate{Assert(Parse("draft email to alex@example.com subject Hello\r\nBcc: other@example.com",now)==null,"Header injection accepted");});
   test("Native agenda phrases select calendar day or week web views",delegate{foreach(string text in new[]{"show calendar tomorrow","what's on my calendar today?","calendar this week","open my Google calendar today","show my events today","what is on my schedule tomorrow"}){var p=Parse(text,now);Assert(p!=null&&p.Action=="open-agenda"&&new Uri(p.Url).Host=="calendar.google.com","Agenda variation failed: "+text);}});
   test("Tomorrow agenda uses the machine local calendar date",delegate{var p=Parse("show calendar tomorrow",now);string expected=TimeZoneInfo.ConvertTimeFromUtc(now,TimeZoneInfo.Local).Date.AddDays(1).ToString("yyyy/M/d",System.Globalization.CultureInfo.InvariantCulture);Assert(p.Url.EndsWith("/day/"+expected),"Tomorrow used wrong timezone");});
   test("Event text creates a prefilling plan with explicit time",delegate{var p=Parse("schedule event Team catchup tomorrow at9am for30min",now);Assert(p!=null&&p.Action=="create-event"&&p.Url.Contains("action=TEMPLATE")&&p.Url.Contains("text=Team%20catchup")&&p.Description.Contains("30 minutes")&&p.Description.Contains("Review and save"),"Calendar plan missing review or timing");});
   test("Event editor encodes title and UTC date span",delegate{var p=Parse("add calendar event Budget & notes 2026-11-03 at 15:30 for 1 hr",now);Assert(p!=null&&p.Url.Contains("text=Budget%20%26%20notes")&&p.Url.Contains("%2F")&&p.Description.Contains("60 minutes"),"Event URL fields were merged");});
   test("Ambiguous and invalid event times do not create a plan",delegate{foreach(string text in new[]{"schedule event Meeting tomorrow at 3","schedule event Meeting tomorrow at 25:00","schedule event Meeting tomorrow at 9am for 0 min","schedule event Meeting 2026-02-31 at 9am"})Assert(Parse(text,now)==null,"Invalid event time accepted: "+text);});
   test("Google web destinations are fixed HTTPS hosts and paths",delegate{foreach(string bad in new[]{"https://mail.google.com.evil.example/mail/","http://mail.google.com/mail/","https://mail.google.com/url?q=https://evil.example","https://calendar.google.com/url?q=bad","https://u:p@mail.google.com/mail/","javascript:alert(1)"})Assert(!GoogleWebWorkflows.IsTrusted(bad),"Untrusted Google URL accepted");});
   test("Native Google setup does not claim OAuth connection",delegate{foreach(string text in new[]{"connect my Google account","connect Gmail","Google setup"}){var result=Commands.Parse(text,new StoredState(),now);Assert(result.GoogleSetup&&result.GoogleWorkflow==null&&result.Url==null&&result.Message.Contains("browser account"),"Native connection claim is misleading");}});
   test("Google workflows leave local reminders and account storage unchanged",delegate{var state=new StoredState();int count=state.Shortcuts.Count;var result=Commands.Parse("draft email to alex@example.com subject Private note body User entered only",state,now);Assert(result.GoogleWorkflow!=null&&result.Url==null&&state.Reminders.Count==0&&state.PendingAlerts.Count==0&&state.Shortcuts.Count==count,"Draft text was stored or directly navigated");});
   test("Oversized web draft yields a clear local response",delegate{var result=Commands.Parse("draft email to alex@example.com subject Hello body "+new string('x',1600),new StoredState(),now);Assert(result.GoogleWorkflow==null&&result.Message.Contains("short"),"Oversized draft became navigation");});
  }
 }
}
